INSERT INTO `artist` VALUES (2,6,'Mai Mộng Mơ','Chuyên gia nhạc Lofi và Ambient.','https://pub-1f9b74cb44204e84b3dd30bb4df6a1e2.r2.dev/artistscover/1766903560416-ð·ðð».jfif',1,'APPROVED','2025-11-02 05:13:52','2025-12-28 13:32:40'),(3,7,'Jazz Man','Nghệ sĩ nhạc Jazz fusion kinh nghiệm.','https://pub-1f9b74cb44204e84b3dd30bb4df6a1e2.r2.dev/artistscover/1766903739274-CHA EUNWOO.jfif',1,'APPROVED','2025-11-02 05:13:52','2025-12-28 13:35:39'),(5,1,'Hien The First','Nghệ sĩ pop-ballad.','https://pub-1f9b74cb44204e84b3dd30bb4df6a1e2.r2.dev/artistscover/1766903560416-ð·ðð».jfif',1,'REJECTED','2025-11-02 06:11:11','2025-12-28 13:39:47'),(6,2,'L.A.M.E','Rapper underground.','https://pub-1f9b74cb44204e84b3dd30bb4df6a1e2.r2.dev/artistscover/1766903548532-moka - 250825.jfif',1,'APPROVED','2025-11-02 06:11:11','2025-12-28 13:32:28'),(23,28,'Band','Hôm nay bạn có ý tưởng gì?','https://pub-1f9b74cb44204e84b3dd30bb4df6a1e2.r2.dev/artistscover/1765094436190-hai mÆ°Æ¡i hai (22).jpg',1,'APPROVED','2025-11-06 01:44:30','2025-12-28 14:50:13'),(32,NULL,'Sơn Tùng MTP','Sơn Tùng M-TP – biểu tượng của làn sóng V-Pop hiện đại.\r\nGiọng hát cuốn hút, tư duy âm nhạc khác biệt và tinh thần “tự làm nên phong cách” giúp anh trở thành một trong những nghệ sĩ có tầm ảnh hưởng mạnh nhất tại Việt Nam.\r\n\r\nTừ “Lạc Trôi”, “Chạy Ngay Đi” đến “Hãy Trao Cho Anh”, mỗi sản phẩm đều mang dấu ấn riêng: giai điệu bắt tai, visuals đỉnh cao và tinh thần không ngừng đổi mới.\r\nKhông chỉ là ca sĩ, anh còn là nhạc sĩ – producer – founder của M-TP Entertainment, định hình con đường nghệ thuật bằng sự táo bạo và sáng tạo.\r\n\r\nSơn Tùng M-TP – âm nhạc chất, phong cách độc, tinh thần dẫn đầu.','https://pub-1f9b74cb44204e84b3dd30bb4df6a1e2.r2.dev/artistscover/1765035932168-SonTung.jpg',1,'APPROVED','2025-12-06 22:45:33','2025-12-06 22:45:33'),(33,NULL,'HIEUTHUHAI','Với các bản hit như “Không Phải Gu”, “Anh Chưa Thương Em Đâu”, “Phòng Trọ 3 Người”, “Sau Này Chúng Ta Giàu”, Hiếu Thứ Hai ghi dấu bằng flow mềm, lyric gần gũi và cá tính vừa lầy, vừa tình cảm.\r\nAnh đại diện cho thế hệ nghệ sĩ trẻ tự do, sáng tạo và dám kể câu chuyện của riêng mình.','https://pub-1f9b74cb44204e84b3dd30bb4df6a1e2.r2.dev/artistscover/1765036796074-HieuThuHai.jpg',1,'APPROVED','2025-12-06 22:48:18','2025-12-06 22:48:18'),(34,NULL,'Bích Phương','Bích Phương – giọng ca nữ mang màu sắc pop hiện đại và cá tính riêng biệt của V-Pop.\r\nCô nổi bật với phong cách âm nhạc quyến rũ, cảm xúc nhưng luôn có nét tinh tế, trưởng thành và đậm chất nghệ sĩ.\r\n\r\nTừ những bản hit như “Bùa Yêu”, “Đi Đu Đưa Đi”, “Mình Yêu Nhau Đi”, “Từ Chối Nhẹ Nhàng Thôi”, Bích Phương ghi dấu bằng chất nhạc catchy, hình ảnh chỉn chu và concept MV luôn được đầu tư kỹ lưỡng.\r\nCô đại diện cho thế hệ nghệ sĩ nữ dám thử nghiệm, dám đổi mới và luôn tạo ra xu hướng riêng.','https://pub-1f9b74cb44204e84b3dd30bb4df6a1e2.r2.dev/artistscover/1765036752118-BichPhuong.jfif',1,'APPROVED','2025-12-06 22:50:04','2025-12-06 22:59:12'),(35,NULL,'Taylor Swift','Taylor Alison Swift là một ca sĩ, nhạc sĩ, diễn viên âm nhạc người Mỹ. Cô là ca sĩ–nhạc sĩ sở hữu khả năng kể chuyện bằng âm nhạc đầy cảm xúc, biến mỗi bài hát thành một lát cắt chân thật của cuộc sống, tình yêu và hành trình trưởng thành.\r\n\r\nTừ những bản hit mang dấu ấn pop như “Shake It Off”, “Blank Space”, “Style”, “Lover” cho đến các album mang màu sắc indie/folk như “Folklore” và “Evermore”, Taylor luôn dẫn đầu xu hướng và liên tục làm mới chính mình.\r\nVới hàng loạt giải Grammy cùng lượng fan khổng lồ toàn cầu, cô đã trở thành biểu tượng văn hoá của thế hệ mới.','https://pub-1f9b74cb44204e84b3dd30bb4df6a1e2.r2.dev/artistscover/1765036318063-Taylor.jpg',1,'APPROVED','2025-12-06 22:51:58','2025-12-06 22:57:52'),(36,NULL,'Chi Pu','Từ diễn viên, idol cho đến ca sĩ, Chi Pu chứng minh sự nỗ lực và quyết tâm trên con đường âm nhạc bằng hình ảnh chỉn chu, phong cách thời thượng và tinh thần không ngại thử thách.\r\n\r\nVới các sản phẩm như “Anh Ơi Ở Lại”, “Mời Anh Vào Team Em”, “Sashimi”, “Từ Hôm Nay”, Chi Pu tạo dấu ấn bằng giai điệu bắt tai, visual đẹp mắt và concept luôn được đầu tư.\r\nCô mang năng lượng của nghệ sĩ thế hệ mới: tự tin, sắc sảo và luôn hướng đến sự bứt phá.','https://pub-1f9b74cb44204e84b3dd30bb4df6a1e2.r2.dev/artistscover/1765036497947-ChiPu.jpg',1,'APPROVED','2025-12-06 22:54:58','2025-12-06 22:54:58'),(37,NULL,'Ariana Grande','Ariana Grande – giọng ca pop powerhouse với chất giọng cao vút, kỹ thuật tinh tế và phong cách âm nhạc đầy hiện đại.\r\nCô nhanh chóng trở thành một trong những nữ nghệ sĩ có sức ảnh hưởng lớn nhất thế giới nhờ khả năng biến hoá đa dạng giữa pop, R&B và dance.\r\n\r\nVới loạt hit đình đám như “7 rings”, “thank u, next”, “Into You”, “No Tears Left To Cry”, “One Last Time”, Ariana kết hợp giai điệu bắt tai, visual thời thượng và cá tính nghệ sĩ đầy tự tin.\r\nCô mang năng lượng của một pop diva mới — mạnh mẽ, quyến rũ và luôn dẫn đầu xu hướng.','https://pub-1f9b74cb44204e84b3dd30bb4df6a1e2.r2.dev/artistscover/1765036533598-ArianaGrande.jpg',1,'APPROVED','2025-12-06 22:55:34','2025-12-06 22:55:34'),(38,NULL,'Amee','Amee – giọng ca trẻ mang màu sắc pop tươi sáng và năng lượng dễ thương đặc trưng.\r\nCô nhanh chóng trở thành gương mặt nổi bật của V-Pop nhờ chất giọng trong trẻo, visual cuốn hút và phong cách âm nhạc đậm chất “teen-pop Việt”.\r\n\r\nVới loạt hit như “Anh Nhà Ở Đâu Thế”, “Sao Anh Chưa Về Nhà”, “Mama Boy”, “Ex’s Hate Me”, “Shay Nắnggg”, Amee mang đến những giai điệu nhẹ nhàng, dễ nghe và giàu cảm xúc.\r\nCô đại diện cho thế hệ nghệ sĩ trẻ hiện đại – tự tin, tràn đầy sức sống và luôn lan toả cảm giác tích cực.','https://pub-1f9b74cb44204e84b3dd30bb4df6a1e2.r2.dev/artistscover/1765036849066-Amee.jpg',1,'APPROVED','2025-12-06 23:00:49','2025-12-06 23:01:04'),(39,NULL,'Selena Gomez','Selena Gomez – ca sĩ, diễn viên và nhà sản xuất âm nhạc sở hữu phong cách trưởng thành, tinh tế và giàu cảm xúc.\r\nCô ghi dấu trong làng nhạc quốc tế với chất giọng ấm, nhẹ nhưng đầy chiều sâu, cùng hình ảnh nghệ sĩ luôn biết cách đổi mới và truyền cảm hứng tích cực.\r\n\r\nVới các hit như “Lose You To Love Me”, “Love You Like A Love Song”, “Calm Down”, “Rare”, “Hands To Myself”, Selena mang đến âm nhạc pop hiện đại pha R&B nhẹ nhàng, dễ nghe và giàu cảm xúc tự sự.\r\nCô cũng là biểu tượng của sự mạnh mẽ, tự chữa lành và hành trình trưởng thành trong spotlight.','https://pub-1f9b74cb44204e84b3dd30bb4df6a1e2.r2.dev/artistscover/1765037497508-SelenaGomez.jfif',1,'APPROVED','2025-12-06 23:05:41','2025-12-06 23:11:38'),(40,NULL,'Noo Phước Thịnh','Noo Phước Thịnh – nam ca sĩ hàng đầu V-Pop với giọng hát cảm xúc, kỹ thuật chắc và phong cách âm nhạc luôn dẫn đầu xu hướng.\r\nAnh được yêu thích bởi hình ảnh lịch lãm, chỉn chu và khả năng làm chủ sân khấu mạnh mẽ.\r\n\r\nVới loạt hit như “Mãi Mãi Bên Nhau”, “Cause I Love You”, “Thương Em Là Điều Anh Không Thể Ngờ”, “Chạm Khẽ Tim Anh Một Chút Thôi”, Noo Phước Thịnh khẳng định vị trí bằng giai điệu pop ballad sâu lắng, kết hợp R&B hiện đại và visual được đầu tư.\r\n\r\nAnh là đại diện tiêu biểu cho thế hệ nghệ sĩ nam mang màu sắc tinh tế – chuyên nghiệp – cảm xúc, luôn giữ vững phong độ và không ngừng làm mới phong cách âm nhạc.','https://pub-1f9b74cb44204e84b3dd30bb4df6a1e2.r2.dev/artistscover/1765037395891-NooPuocThinh.jfif',1,'APPROVED','2025-12-06 23:07:40','2025-12-06 23:09:56'),(41,NULL,'Đen Vâu','Đen Vâu – rapper mang màu sắc mộc mạc, sâu sắc và đầy chất đời của rap Việt.\r\nÂm nhạc của Đen không ồn ào, không khoe kỹ thuật, mà chạm vào cảm xúc bằng lyric chân thật, gần gũi và suy tư về cuộc sống, hành trình trưởng thành và những nỗi niềm rất Việt Nam.\r\n\r\nVới các bài hit như “Mang Tiền Về Cho Mẹ”, “Hai Triệu Năm”, “Bài Này Chill Phết”, “Trốn Tìm”, “Đi Về Nhà”, Đen tạo ra chỗ đứng riêng bằng dòng nhạc rap mang hơi thở thi ca, nhẹ nhàng nhưng thấm đượm ý nghĩa.\r\nPhong cách giản dị, chân thành và luôn giữ chất bụi đời khiến anh trở thành biểu tượng của sự “tự do trong âm nhạc”.','https://pub-1f9b74cb44204e84b3dd30bb4df6a1e2.r2.dev/artistscover/1765037487644-DenVau.jpg',1,'APPROVED','2025-12-06 23:09:02','2025-12-06 23:11:28'),(44,10,'Report','Hồ sơ đang chờ Admin duyệt...','https://pub-1f9b74cb44204e84b3dd30bb4df6a1e2.r2.dev/artistscover/1766903560416-ð·ðð».jfif',1,'APPROVED','2025-12-28 20:07:27','2025-12-28 20:07:48');
