INSERT INTO `lyrics` VALUES (2,7,'Đây là lời bài hát test cho bài ID 6.Nơi mọi lỗi lầm được sửa chữa.[Chorus]Lame Music, Lame Music, Code chạy ngon lành!','en','2025-11-02 05:13:52','2025-11-08 18:55:30'),(4,6,'Đây là lời bài hát test cho bài ID 6.\r\nNơi mọi lỗi lầm được sửa chữa.\r\n\r\n[Chorus]\r\nLame Music, Lame Music, Code chạy ngon lành!','vi','2025-11-02 21:54:36','2025-12-28 13:44:02'),(6,24,'[Intro]\r\nChills\r\n\r\n[Verse 1]\r\nNew York back in August, tenth floor balcony\r\nSmoke is floating over Jane and Greenwich street\r\nGoosebumps from your wild eyes when they\'re watching me\r\nShivers dance down my spine, head down to my feet\r\n\r\n[Pre-Chorus]\r\nSwimming in your eyes, in your eyes, in your eyes\r\nEgyptian blue\r\nSomething I\'ve never had without you\r\n\r\n[Chorus]\r\nYou\'re giving me chills at a hundred degrees\r\nIt\'s better than pills how you put me to sleep\r\nCalling your name, the only language I can speak\r\nTaking my breath, a souvenir that you can keep\r\n\r\n[Post-Chorus]\r\nGiving me chills\r\nChills\r\n\r\n[Verse 2]\r\nSunset Tower lobby, waiting there for me\r\nIn the elevator, fumble for your key\r\nKissed in every corner, Presidential Suite\r\nOpened that Bordeaux from 1993\r\n\r\n[Pre-Chorus]\r\nSwimming in your eyes, in your eyes, in your eyes\r\nEgyptian blue\r\nSomething I\'ve never had without you\r\n\r\n[Chorus]\r\nYou\'re giving me chills at a hundred degrees\r\nIt\'s better than pills how you put me to sleep\r\nCalling your name, the only language I can speak\r\nTaking my breath, a souvenir that you can keep\r\n\r\n[Post-Chorus]\r\nGiving me chills\r\n\r\n[Bridge]\r\nTake my, take-take my breath away just like\r\nTake my breath away just like a souvenir\r\nTake my, take-take my breath away just like\r\nTake my breath away just like a souvenir\r\n\r\n[Chorus]\r\nYou\'re giving me chills at a hundred degrees (A hundred)\r\nIt\'s better than pills how you put me to sleep (Puts me, yeah)\r\nCalling your name, the only language I can speak\r\nTaking my breath, a souvenir that you can keep\r\n\r\n[Outro]\r\nGiving me chills\r\nTake my, take-take my breath away just like (You\'re giving me chills)\r\nTake my breath away just like a souvenir\r\nGiving me chills\r\nTake my, take-take my breath away just like (You\'re giving me chills)\r\nTake my breath away just like a souvenir','en','2025-12-06 23:19:25','2025-12-06 23:19:25'),(7,25,'Bài hát: Feel Me - Selena Gomez\r\n\r\n[Verse 1]\r\nNo one love you like I love ya\r\nNever cheated, never lied\r\nNever put no one above ya\r\nI gave you space and time\r\nAnd now you\'re telling me you miss it\r\nAnd I\'m still on your mind\r\nWe were one in a million\r\nOur love is hard to find\r\n\r\n[Pre-Chorus]\r\nDo you stay up late just so you don\'t dream?\r\n\r\n[Chorus]\r\nEvery time your lips touch another\r\nI want you to feel me\r\nI want you to feel me\r\nEvery time you dance with somebody\r\nI want you to feel me\r\nI want you to feel me\r\n\r\n[Post-Chorus]\r\nDo your days get a little bit longer?\r\nNights get a little bit colder?\r\nHeartbeat a little bit louder?\r\nHah-ah-ah-ah-oh\r\nDays get a little bit longer?\r\nNights get a little bit colder?\r\nHeartbeat a little bit louder?\r\nHah-ah-ah-ah-oh\r\n\r\n[Verse 2]\r\nWhen you\'re running, who you run to?\r\nWhere do you go to hide?\r\nWhen she ain\'t giving you enough to get you through the night\r\nWon\'t be caught up in the middle\r\nThrough your highs and your lows\r\nBaby, \'long as you\'re not with me, you\'ll always be alone\r\n\r\n[Pre-Chorus]\r\nDo you stay up late, just so you don\'t dream?\r\n\r\n[Chorus]\r\nEvery time your lips touch another\r\nI want you to feel me\r\nI want you to feel me\r\nEvery time you dance with somebody\r\nI want you to feel me\r\nI want you to feel me\r\n\r\n[Post-Chorus]\r\nDo your days get a little bit longer?\r\nNights get a little bit colder?\r\nHeartbeat a little bit louder?\r\nHah-ah-ah-ah-oh\r\nDays get a little bit longer?\r\nNights get a little bit colder?\r\nHeartbeat a little bit louder?\r\nHah-ah-ah-ah-oh\r\n\r\n[Breakdown]\r\nFeel me (feel me)\r\nFeel me (feel me)\r\nFeel me (feel me)\r\n\r\n[Chorus]\r\nEvery time your lips touch another\r\nI want you to feel me\r\nI want you to feel me\r\nEvery time you dance with somebody\r\nI want you to feel me\r\nI want you to feel me\r\n\r\n[Post-Chorus]\r\nDo your days get a little bit longer? (feel me)\r\nNights get a little bit colder? (feel me)\r\nHeartbeat a little bit louder?\r\nHah-ah-ah-ah-oh (feel me)\r\nDays get a little bit longer? (feel me)\r\nNights get a little bit colder? (feel me)\r\nHeartbeat a little bit louder?\r\nHah-ah-ah-ah-oh\r\n\r\n[Outro]\r\nEvery time your lips touch another\r\nHah-ah-ah-ah-oh\r\nEvery time you dance with somebody','en','2025-12-06 23:23:33','2025-12-06 23:23:33'),(9,27,'Bài hát: Same Old Love - Selena Gomez\r\n\r\nTake away all your things and go\r\nYou can\'t take back what you said, I know\r\nI\'ve heard it all before, at least a million times\r\nI\'m not one to forget, you know\r\n\r\nI don\'t believe, I don\'t believe it\r\nYou left in peace, left me in pieces\r\nToo hard to breathe, I\'m on my knees\r\nRight now, \'ow\r\n\r\nI\'m so sick of that same old love, that ***, it tears me up\r\nI’m so sick of that same old love, my body\'s had enough\r\nOh, (that same old love)\r\nOh, (that same old love)\r\nI’m so sick of that same old love, feels like I\'ve blown apart\r\nI’m so sick of that same old love, the kind that breaks your heart\r\nOh, (that same old love)\r\nOh, (that same old love)\r\n\r\nI\'m not spending any time, wasting tonight on you\r\nI know, I\'ve heard it all\r\nSo don\'t you try and change your mind\r\nCause I won\'t be changing too, you know\r\n\r\nYou can\'t believe, still can\'t believe it\r\nYou left me in peace, left me in pieces\r\nToo hard to breathe, I\'m on my knees\r\nRight now, \'ow\r\n\r\nI\'m so sick of that same old love, that ***, it tears me up\r\nI’m so sick of that same old love, my body\'s had enough\r\nOh, (that same old love)\r\nOh, (that same old love)\r\nI’m so sick of that same old love, feels like I\'ve blown apart\r\nI’m so sick of that same old love, the kind that breaks your heart\r\nOh, (that same old love)\r\nOh, (that same old love)\r\n\r\nI\'m so sick of that, so sick of that love\r\nI\'m so sick of that, so sick of that love\r\nI\'m so sick of that, so sick of that love\r\nI\'m so sick of that, so sick of that love\r\n\r\nI\'m so sick of that same old love, that ***, it tears me up\r\nI’m so sick of that same old love, my body\'s had enough\r\nOh, (that same old love)\r\nOh, (that same old love)\r\nI’m so sick of that same old love, feels like I\'ve blown apart\r\nI’m so sick of that same old love, the kind that breaks your heart\r\nOh, (that same old love)\r\nOh, (that same old love)','en','2025-12-06 23:43:30','2025-12-06 23:43:30'),(10,28,'Took you like a shot\r\nThought that I could chase you with a cold evening\r\nLet a couple years water down how I\'m feeling about you\r\n♪\r\nAnd every time we talk\r\nEvery single word builds up to this moment\r\nAnd I gotta convince myself I don\'t want it\r\nEven though I do (Even though I do)\r\nYou could break my heart in two\r\nBut when it heals, it beats for you\r\nI know it\'s forward, but it\'s true\r\nI wanna hold you when I\'m not supposed to\r\nWhen I\'m lying close to someone else\r\nYou\'re stuck in my head and I can\'t get you out of it\r\nIf I could do it all again\r\nI know I\'d go back to you\r\n\r\nI know I\'d go back to you\r\n♪\r\nI know I\'d go back to you\r\nWe never got it right\r\nPlaying and replaying old conversations\r\nOverthinking every word and I hate it\r\n\'Cause it\'s not me\r\nAnd what\'s the point in hiding?\r\nEverybody knows we got unfinished business\r\nAnd I\'ll regret it if I didn\'t say\r\nThis isn\'t what it could be (Isn\'t what it could be)\r\nYou could break my heart in two\r\nBut when it heals, it beats for you\r\nI know it\'s forward, but it\'s true\r\nI wanna hold you when I\'m not supposed to\r\nWhen I\'m lying close to someone else\r\nYou\'re stuck in my head and I can\'t get you out of it\r\nIf I could do it all again\r\nI know I\'d go back to you\r\nI know I\'d go back to you\r\n♪\r\nI know I\'d go back to you\r\nI\'d go back to you, I\'d go back to you\r\nWhat was there wasn\'t sure\r\nBut I\'d go back to you (I know I\'d go back to you)\r\nYou can break my heart in two\r\nBut when it heals, it beats for you\r\nI know it\'s forward, but it\'s true\r\nWon\'t lie, I\'d go back to you\r\nYou know, my thoughts are running loose\r\nIt\'s just a thing you make me do\r\nAnd I could fight, but what\'s the use?\r\nI know I\'d go back to you\r\nI wanna hold you when I\'m not supposed to (When I\'m not supposed to)\r\nWhen I\'m lying close to someone else\r\nYou\'re stuck in my head and I can\'t get you out of it\r\nIf I could do it all again\r\nI know I\'d go back to you\r\nI\'d go back to you\r\nI\'d go back to you\r\nI know I\'d go back to you\r\nI\'d go back to you, I\'d go back to you\r\nI know I\'d go back to you','en','2025-12-06 23:46:09','2025-12-06 23:46:09'),(11,29,'','vi','2025-12-07 00:11:22','2025-12-07 00:18:53'),(12,30,'','vi','2025-12-07 00:13:13','2025-12-07 00:18:44'),(13,31,'Làm một ngọn cây bay lên không trung\r\nLà làn mây đang trôi ung dung\r\nĐợi nắng lên yahh\r\nThật nhiều điều không cho ta yên vui\r\nĐừng để bị lôi đôi chân xuống đáy Mariana yeah\r\n\r\nĐã từng bị vây trong cơn u mê\r\nTừng được nghe câu “Nó không làm được đâu”\r\nSáng nay thức giấc chợt nghe thấy lòng bồi hồi từ trong ra\r\nThấy được cuộc đời này còn yêu ta vô cùng\r\nTốt nhất là nên yêu đời\r\n\r\nTa thường tự ngẫm điều cũ kỹ\r\nRốt cuộc bao nhiêu là đủ nhỉ\r\nNhảy nhót giữa đời như lũ khỉ.\r\nNgày thì kiếm cơm đêm ngủ kỹ.\r\nLắng nghe cuộc đời đang thủ thỉ\r\nVà luôn giữ kỹ\r\nKhông hề đàm phán với lũ quỷ\r\nDù chỉ là sợi tóc, hay là một góc trong linh hồn\r\n\r\nYêu đời là cách ta sinh tồn\r\nKhông cao không ngạo không lowkey yah\r\nTội gì mà không yêu lấy cuộc đời mình, ta yêu đời lắm\r\nYêu đời từ khi mà nó còn tối tăm, chưa biết khi nào nó ngời thẳm\r\nKhi mà ta vẫn, vẫn còn chưa biết phải làm sao với cuộc đời mình\r\nKhi mà ta vẫn, vẫn say sưa viết mà biết không ai sẽ thuộc lời mình\r\n\r\nyah Khi nó còn là vô bổ\r\nMấy thằng điên và thô lỗ\r\nRap tới khi mà khô cổ\r\nVới đứa bạn làm show lỗ\r\nCó mấy thằng bị xô đổ\r\nBị cơm áo về gô cổ\r\nKhi lời nhạc còn sơ hở và thơ dở\r\n\r\nNgủ dưới bầu trời như người cơ nhỡ\r\nKhông chăn không đệm cho niềm mơ thở\r\nVà vẫn luôn yêu đời chưa bao giờ thờ ơ\r\nYêu đời đôi khi cũng là khá khổ công\r\nNhưng phải có ngày tàn mới có ngày lá trổ bông\r\n\r\nCó khi cơn mơ tơi tả chỗ vá chỗ không\r\nNhưng mà sau tất cả lòng chưa thành đá tổ ong\r\nXem mình ngày mai là đồng minh và xem minh hôm qua là đối thủ\r\nTìm cách mà lấp đầy lòng tin, phải tin mình tin người thì mới đủ\r\nYêu cả những thứ ta phải là, cảm hứng luôn là đầu mối cũ\r\nYêu đời đủ nhiều thì nỗi buồn cũng trở nên dễ chịu như gối ngủ\r\n\r\nCúi thấp đầu hơn thấp đầu hơn thấp đầu hơn\r\nNgày tháng sẽ làm cho tất cả trôi mất màu sơn\r\nĐời không nhiều luyến tiếc trong trời chiều tím biếc\r\nNói với bản thân không được buông không được buông\r\n\r\nSáng nay lên đồi xem lá liệng xuống gốc chưa\r\nMuốn tắm trong nắng vàng và há miệng uống nước mưa\r\nNếu không yên lòng thì nép mình dưới bóng cây\r\nVà nhớ luôn yêu đời vì nó chỉ dài mấy lóng tay\r\n\r\nLàm một ngọn cây bay lên không trung\r\nLà làn mây đang trôi ung dung\r\nĐợi nắng lên yahh\r\n\r\nThật nhiều điều không cho ta yên vui\r\nĐừng để bị lôi đôi chân xuống đáy Mariana yeah\r\nĐã từng bị vây trong cơn u mê\r\nTừng được nghe câu “Nó không làm được đâu” ngàn lần\r\n\r\nSáng nay thức giấc chợt nghe thấy lòng bồi hồi từ trong ra\r\nThấy được cuộc đời này còn yêu ta vô bờ\r\nTốt nhất là nên yêu đời\r\n\r\nTầm tuổi nào cũng có những chông chênh,\r\nNhư con thuyền gỗ bị cong vênh,\r\nChỉ có tự mình uốn nắn\r\nChưa từng đánh mất đi lòng tin,\r\nChắt lọc nhiều thông tin,\r\nNhủ lòng đừng muốn thắng\r\nCũng đừng sợ thua thì bày keo khác\r\nMột ngày trong đời là một ngày reo hát\r\nNhư khi còn bé đem trang vẻ xé mà gấp máy bay\r\nChẳng mong đợi vì, không ích lợi gì chỉ vì thấy nó hay\r\nVà biết mình may mắn nên thường chắp lấy tay\r\n\r\nCúi mặt nhìn đời, thấy mình là một trong muôn vàn người lao động\r\nNgước lên nhìn trời, cám ơn đời cho con mắt nhìn trời cao rộng\r\nĐể biết mình đã đang và chưa từng lớn lao\r\nHay trung tâm thế giới\r\nYêu cả những lần từng đớn đau\r\n\r\nBằng một tâm thế mới\r\nTiếng đời ngân nga từ trong ta khẽ khàng\r\nVà xin được yêu thương những người đang cạnh mình\r\nNon xanh nước biếc như Phong Nha Kẻ Bàng\r\nTa đi qua thung lũng như là Phan Mạnh Quỳnh oh\r\n\r\nMuốn nằm chơi giữa tảng mây to\r\nLàm nhà dưới hàng cây chò\r\nTa sẽ lại cùng nhau bày trò\r\nSafe and Sound như là Taylor','vi','2025-12-07 00:17:14','2025-12-07 00:17:14'),(14,32,'Bài hát: Cause I Love You - Noo Phước Thịnh\r\n\r\nGiờ người đang bước bên ai không phải anh\r\nGiờ người đang say bên ai không phải anh\r\nChắc do anh vô tâm hay tình em đã phai phôi nhạt nhòa\r\n\r\nGiờ người bên ai anh mong em sẽ vui\r\nGiờ người bên ai anh mong em bình yên\r\nĐể em thôi bận lòng, anh sẽ ra đi vì em\r\n\r\nKhép kín kí ức ấy vào tim\r\nAnh khép kín những nỗi nhớ đong đầy\r\nĐể ngày dài trôi mãi, anh sẽ thôi không u sầu\r\nCho anh thôi không nghĩ về em\r\nVà cho anh thôi thao thức đêm dài\r\nGiờ còn ai kề bên, còn ai đêm thâu nồng say\r\n\r\nLối cũ ấy ta đã cùng nhau kề vai bên hiên trao chiếc hôn đầu\r\nSao giờ xa xôi quá, hai đứa hai nơi phương trời\r\nAnh hoang mang nơi đáy vực sâu, từ khi em xa anh mang nỗi đau\r\nMuộn màng nhưng anh biết\r\nAnh đã thôi không còn yêu\r\n\r\nGiờ người đang bước bên ai không phải anh\r\nGiờ người đang say bên ai không phải anh\r\nChắc do anh vô tâm hay tình em đã phai phôi nhạt nhòa\r\n\r\nGiờ người bên ai anh mong em sẽ vui\r\nGiờ người bên ai anh mong em bình yên\r\nĐể em thôi bận lòng, anh sẽ ra đi vì em\r\n\r\nTell me babe eh eh\r\nWhy did you make me cry\r\nTell me babe eh eh\r\nI miss you every night\r\n\'Cause i love you love you love you','vi','2025-12-07 00:26:03','2025-12-07 00:26:03'),(15,33,'Bài hát: Như Phút Ban Đầu - Noo Phước Thịnh\r\n\r\nVì em anh như người điên mất trí\r\nVì em anh như chẳng còn biết nghĩ suy\r\nVì anh đã trót lỡ đắm say em không bận tâm mai sau thế nào\r\nDù mai sau kia gập ghềnh sóng gió\r\nDù mai sau kia dòng đời có cuốn xoay\r\nDù nhắm mắt anh vẫn nắm tay em như ngày ta bắt đầu\r\n\r\nNhìn vào sâu đôi mắt\r\nEm có biết trong anh muốn nói điều gì\r\nRằng từ lâu đôi ta đã thuộc về nhau\r\nNgười làm anh gục ngã\r\nTừ ánh mắt đôi môi cử chỉ mỉm cười\r\nRằng từ đây anh muốn bên em suốt đời\r\n\r\nVì em anh như người điên mất trí\r\nVì em anh như chẳng còn biết nghĩ suy\r\nVì anh đã trót lỡ đắm say em không bận tâm mai sau thế nào\r\nDù mai sau kia gập ghềnh sóng gió\r\nDù mai sau kia dòng đời có cuốn xoay\r\nDù nhắm mắt anh vẫn nắm tay em như ngày ta bắt đầu\r\n\r\nDẫu ngày mưa hay ngày nắng chói chang\r\nEm vẫn cứ dịu dàng, vẫn muốn bên em thật lâu\r\nPhút đầu tiên em đã lấy mất đi linh hồn\r\nNgười làm anh xót xa con tim ngỡ ngàng\r\nVì em anh như người điên mất trí\r\nVì em anh như chẳng còn biết nghĩ suy\r\nVì anh đã trót lỡ đắm say em không bận tâm mai sau thế nào\r\nDù mai sau kia gập ghềnh sóng gió\r\nDù mai sau kia dòng đời có cuốn xoay\r\nDù nhắm mắt anh vẫn nắm tay em như ngày ta bắt đầu\r\n\r\nVì em anh như người điên mất trí\r\nVì em anh như chẳng còn biết nghĩ suy\r\nVì anh đã trót lỡ đắm say em không bận tâm mai sau thế nào\r\nDù mai sau kia gập ghềnh sóng gió\r\nDù mai sau kia dòng đời có cuốn xoay\r\nDù nhắm mắt anh vẫn nắm tay em như ngày ta bắt đầu\r\n\r\nVì em anh như người điên mất trí\r\nVì em anh như chẳng còn biết nghĩ suy\r\nVì anh đã trót lỡ đắm say em không bận tâm mai sau thế nào\r\nDù mai sau kia gập ghềnh sóng gió\r\nDù mai sau kia dòng đời có cuốn xoay\r\nDù nhắm mắt anh vẫn nắm tay em như ngày ta bắt đầu','vi','2025-12-07 00:29:59','2025-12-07 00:29:59'),(16,34,'Yêu em, dù là đơn phương thế thôi\r\nSao chẳng thể nói ra trước đôi môi kia\r\nThương em, là điều anh không thể ngờ\r\nNgăn nỗi nhớ cũng không thể ngăn trái tim\r\nNgần ngại chôn sâu yêu thương\r\nAnh giấu đi tâm sự mỗi khi bên cạnh nhau\r\nChỉ biết lặng thinh ngắm nhìn\r\nMột ngôi sao nhỏ bé làm tim anh mãi mong chờ\r\nLà anh cố chấp yêu em\r\nDù không thể nói thành lời\r\nVì dại khờ anh thu mình trong suy tư của em\r\nDù muộn sầu hay thương nhớ anh xin một mình mang hết\r\nChỉ mong bờ mi em không vương chút buồn\r\nVà nụ cười em luôn trên bờ môi\r\nThương em, là điều anh không thể ngờ\r\nNgăn nỗi nhớ cũng không thể ngăn trái tim\r\nNgần ngại chôn sâu yêu thương\r\nAnh giấu đi tâm sự mỗi khi bên cạnh nhau\r\nChỉ biết lặng thinh ngắm nhìn\r\nMột ngôi sao nhỏ bé làm tim anh mãi mãi mong chờ\r\nLà anh cố chấp yêu em\r\nDù không thể nói thành lời\r\nVì dại khờ anh thu mình trong suy tư của em\r\nDù muộn sầu hay thương nhớ anh xin một mình mang hết\r\nChỉ mong bờ mi em không vương chút buồn\r\nVà nụ cười em luôn trên bờ môi\r\nTrọn yêu thương này trao cho em\r\nTrọn tâm tư này anh giữ lấy\r\nSẽ bên cạnh em dẫu cho ngày mai\r\nNgười rời xa anh\r\nRời xa anh mãi\r\nLà anh cố chấp yêu em\r\nLà anh cố chấp yêu em\r\nDù không thể nói thành lời\r\nVì dại khờ anh thu mình trong suy tư của em\r\nDù muộn sầu hay thương nhớ anh xin một mình mang hết\r\nChỉ mong bờ mi em không vương chút buồn\r\nVà nụ cười em luôn trên bờ môi\r\nChỉ mong bờ mi em không vương chút buồn\r\nVà nụ cười em luôn trên bờ môi...','vi','2025-12-07 00:31:20','2025-12-07 00:31:20'),(17,35,'Bài hát: Mất Em - Noo Phước Thịnh, Noo Phước Thịnh\r\n\r\nMột phút bối rối, trống vắng, vỡ nát trong anh,\r\nThoáng qua bao nhiêu mộng mơ đã vụt mất.\r\nThấy ai kia đang bên cạnh em đi ngoài phố,\r\nNắm tay nhau, môi em cười tươi trong hạnh phúc.\r\nNgày tháng cứ thế mãi giấu tiếng nói yêu em\r\nĐể hôm nay anh phải đau thêm người hỡi.\r\nNhớ mong em yêu em từ lâu em nào biết\r\nTrách cho anh yêu nhưng lại không nói nên lời.\r\n\r\nĐêm hay ngày cũng nhớ em,\r\nThời gian qua từng ngày đợi mong tin em,\r\nTại sao anh, lặng im, chỉ biết yêu trong lòng,\r\nGiọt lệ anh theo em bước ra đi...Hơơ\r\n\r\nĐK:\r\nNếu khi xưa anh không bận tâm bao lời nói,\r\nNếu khi xưa anh không lặng thinh trong niềm nhớ,\r\nNếu khi xưa anh không là bạn thân, để nói yêu em,\r\nThì hôm nay I won’t crying for u,\r\nThì hôm nay I won’t missing for u,\r\nBaby I love u I waiting for u\r\n\r\nCứ thế cứ mãi giấu tiếng nói yêu em\r\nĐể hôm nay anh phải đau thêm người hỡi,\r\nNhớ mong em yêu em từ lâu em nào biết,\r\nTrách cho anh yêu nhưng lại không nói nên lời.\r\nĐêm hay ngày cũng nhớ em,\r\nThời gian qua từng ngày đợi mong tin em,\r\nTại sao anh , lặng im, chỉ biết yêu trong lòng,\r\nGiọt lệ anh theo em bước ra đi...Hơơ\r\n\r\nĐK:\r\nNếu khi xưa anh không bận tâm bao lời nói,\r\nNếu khi xưa anh không lặng thinh trong niềm nhớ\r\nnếu khi xưa anh không là bạn thân, để nói yêu em\r\nThì hôm nay I won’t crying for u,\r\nThì hôm nay I won’t missing for u\r\nBaby I love u and waiting for u\r\n\r\n\r\nBye bye never say good bye\r\nDù em mãi mãi không về đây với anh, I need u\r\nQua bao nhiêu ngày anh vẫn mãi mong em,\r\nĐợi chờ em , em yêu, chờ em mãi ...\r\n\r\nĐK:\r\nNếu khi xưa anh không bận tâm bao lời nói,\r\nNếu khi xưa anh không lặng thinh trong niềm nhớ\r\nnếu khi xưa anh không là bạn thân, để nói yêu em\r\nThì hôm nay I won’t crying for u,\r\nThì hôm nay I won’t missing for u\r\nBaby I love u and waiting for u (2x)','vi','2025-12-07 00:32:37','2025-12-07 00:32:37'),(18,36,'Bài hát: Chạm Khẽ Tim Anh Một Chút Thôi - Noo Phước Thịnh\r\n\r\nChạm nhẹ vào đôi mắt\r\nChạm nhẹ vào bờ vai\r\nChạm nhẹ vào đôi môi\r\nNgày mai xa anh rồi\r\n\r\nChạm nhẹ vào trí nhớ\r\nChạm nhẹ vào cơn mơ\r\nMình đã chạm khẽ vào nhau những ngày ngây thơ\r\nAnh yêu cô gái nhỏ bé\r\n\r\nTin vào những lời bài hát\r\nTin rằng nếu khóc trong mưa sẽ bớt đau hơn\r\nAnh yêu cô gái năm ấy\r\nTin vào những điều viển vông\r\n\r\nRằng tay và tay sẽ nắm lấy nhau tận cuối cuộc đời\r\nThời gian xóa đi những ngây thơ những điều vội vàng như trong giấc mơ\r\nĐể lại những cơn đau vu vơ chẳng còn bất ngờ\r\nMột mai sớm kia em có thấy giữa lồng ngực mình đau khi nhớ anh\r\n\r\nThì đừng vội khóc hãy xiết tay anh nơi e bình yên\r\nĐừng hôn nếu môi em chưa quên dư vị ngọt ngào hai ta đã trao\r\nĐừng ôm nếu em thấy anh ta chẳng thể vỗ về\r\n\r\nĐừng tin nếu chia tay anh ta nói rằng mình không xứng đáng với em\r\nVà đừng vội khóc anh vẫn ở đây cho em bình yên\r\nChạm khẽ tim anh một chút thôi mai xa rồi','vi','2025-12-07 00:33:47','2025-12-07 00:33:47'),(19,37,'Sau tháng ngày vất vả\r\nChỉ ước được trở về nhà\r\nMang trên tay là những món quà\r\nNơi có mẹ và ba\r\nCăn nhà xưa mới là tất cả\r\nKhông phải đô thị xa hoa\r\nKhông tấp nập phố xá\r\nMà tinh mơ có tiếng con gà\r\nSẽ đánh thức thay vì\r\nNghe tiếng chuông báo thức đi cày\r\nNơi xa nhiều thứ mệt lắm\r\nĐôi ba lời câu hỏi thăm\r\nChẳng có một ai quan tâm\r\nThân trai đôi khi cảm thấy sát song\r\nCô đơn sau những ngày dài\r\nKhoảng trống chưa lấp đầy lại\r\nCòn bao deadline cứ chờ đợi mãi\r\nQuê hương thì luôn hoài ngóng\r\nĐêm đêm nằm cứ chờ trông\r\nNghe câu hỏi nhớ nhà không\r\nỞ dưới góc tối nước mắt lưng tròng\r\nPhố đông bão giông\r\nCả sông động hết trong lòng\r\nNếu như phố thành khổ quá\r\nThì trở về nhà đây\r\nMẹ nuôi nhé con\r\nVề mẹ chăm cho bát cơm ngon\r\nĐể nghĩ suy lo lắng chẳng còn\r\nNếu trên phố thị mệt quá\r\nCứ bắt xe về đây\r\nBa mẹ chờ đón\r\nGạt bỏ qua phố xá nơi xa\r\nQuay về đây nhà ta sum vầy\r\nĐâu phải cần Tết đến\r\nChẳng phải chờ xuân tới\r\nMà chỉ cần ta nhớ\r\nLà về nhà với ba\r\nDù là có xa\r\nKhông được làm gì khó ta\r\nMẹ chẳng cần tiền con đâu\r\nChẳng cần con phải lo cho gia đình\r\nMiễn sao con không đau ốm\r\nThật mạnh khỏe quay về nhà mình\r\nThế thôi là mẹ vui lắm\r\nQuây quần mâm cơm\r\nTiếng cười say đắm\r\nBởi những ngày tháng đi xa\r\nNgôi nhà ta chỉ có lặng thầm\r\nNếu như phố thành khổ quá\r\nThì trở về nhà ngay\r\nMẹ nuôi nhé con\r\nVề mẹ chăm cho bát cơm ngon\r\nĐể nghĩ suy lo lắng chẳng còn\r\nNếu trên phố thị mệt quá\r\nCứ bắt xe về đây\r\nBa mẹ chờ đón\r\nGạt bỏ qua phố xá nơi xa\r\nQuay về đây nhà ta sum vầy\r\nMẹ chẳng cần tiền con đâu\r\nChẳng cần con phải lo cho gia đình\r\nMiễn sao con không đau ốm\r\nThật mạnh khỏe quay về nhà mình\r\nThế thôi là mẹ vui lắm\r\nQuây quần mâm cơm\r\nTiếng cười say đắm\r\nBởi những ngày tháng đi xa\r\nNgôi nhà ta chỉ có lặng thầm','vi','2025-12-07 00:37:00','2025-12-07 00:37:00'),(20,38,'Đã đến lúc cần được giải thoát\r\nCố níu kéo cũng chỉ vỡ tan\r\nNhư hoa kia chẳng còn thơm ngát\r\nCố giữ lấy cũng lụi tàn\r\n\r\nNước mắt rơi giữa đời ngổn ngang\r\nƯu tư mang cả trời ký ức\r\nCàng day dứt, càng không cách nào nguôi\r\n\r\nBơ vơ theo dòng người vô hướng\r\nCứ vấn vương rồi lại tổn thương\r\nNhớ không được, mà quên cũng chẳng được\r\nYêu một người sao buồn đến thế?\r\nThương một người sao đau đến thế?\r\nNhớ không được, mà quên cũng không được\r\n\r\n[ĐK:]\r\nCó nhau là điều may mắn, cớ sao không giữ lấy\r\nNếu buông tay chẳng thể quay lại\r\nDẫu ai đã từng gây bao nhớ thương, ngàn lần vương vấn\r\nNắng mưa trên đầu làm sao có ai biết thấu\r\nYêu một người sẽ buồn bao lâu?\r\nTrách ai bây giờ, chỉ biết trách ta vội vàng\r\n\r\nVì yêu là đau là thương thế đấy\r\nVì yêu là say, là bao đắng cay\r\nVì ai đổi thay? Vì ai? Vì ai?','vi','2025-12-07 00:39:03','2025-12-07 00:39:03'),(21,39,'Bài Hát: Chờ Ngày Mưa Tan - Noo Phước Thịnh, Tonny Việt\r\n\r\nMột ngày mưa và em khuất xa nơi anh, bóng dáng cứ phai dần\r\nPhải bao lâu anh mới quên được em?\r\nTừng ngày cứ lặng lẽ bước qua đời anh, thế nhưng giờ tim vẫn đau nhói\r\nVì em...nỗi đau không nhạt phai\r\nVà dòng ký ức khẽ qua, mỗi đêm dài cạnh bên với anh\r\nTỉnh dậy, đôi mắt hoen đi vì khóc...\r\nƯớc mơ của chúng ta...chỉ một cơn mưa đã cuốn trôi tất cả\r\nChiều mưa ...chiều khiến yêu thương lạnh giá.\r\n\r\nTại sao em lại quay bước đi?\r\nTại sao không thể ngừng nhớ em?\r\nDù cho em...chính em rời xa anh\r\nVà anh sẽ chờ một giấc mơ\r\nNắng sẽ về khiến mưa trôi xa...nhẹ nhàng\r\nCơn gió khẽ mang em về bên anh\r\n\r\n[Rap]\r\nSao mưa vươn trên mắt tới mi\r\nRồi thoáng những phút giây, có nhau gần kề\r\nLại cơn mưa đẩy anh đi về, nơi những mơ mộng\r\nChợt vụn vỡ theo những giọt mưa\r\nMau trôi đêm mưa tan nắng đưa em về níu em 1 lần\r\nTrọn từng giấc mơ...cho tin yêu đầy vơi khi em quay lưng đi\r\n\r\nHát\r\nVà dòng ký ức khẽ qua, mỗi đêm dài cạnh bên với anh\r\nTỉnh dậy, đôi mắt hoen đi vì khóc...\r\nƯớc mơ của chúng ta...chỉ một cơn mưa đã cuốn trôi tất cả\r\nChiều mưa ...chiều khiến yêu thương lạnh giá.\r\n\r\n[ĐK]\r\nTại sao em lại quay bước đi?\r\nTại sao không thể ngừng nhớ em?\r\nDù cho em...chính em rời xa anh\r\nVà anh sẽ chờ một giấc mơ\r\nNắng sẽ về khiến mưa trôi xa...nhẹ nhàng\r\nCơn gió khẽ mang em về bên anh\r\n\r\n[RAP]\r\nSao nước vươn trên mắt em sao thời gian không hong khô\r\nKhoảng cách giữa nhiều hơi thở thật gần nhưng mà nó dài không ngờ\r\nChỉ mong chờ: trong giấc mơ ngắn đưa em về\r\nĐêm vẫn còn dài vì anh thao thức cùng tới với những giọt lệ để ê chề\r\nMọi thứ từ đâu vỡ tan, trong hoang man, lí do còn khiến anh ngỡ ngàng\r\nThật bất tàn nhiều phũ phàng chỉ xin 1 lần chờ người ấy\r\nXóa tan cơn mưa mang những điều ước hình ảnh mơ mộng với dòng kí ức\r\nCơn mưa ngọt ngào trăm ngàn nỗi đau\r\n\r\n[Hát]\r\nTại sao em lại quay bước đi?\r\nTại sao không thể ngừng nhớ em?\r\nDù cho em...chính em rời xa anh\r\nVà anh sẽ chờ một giấc mơ\r\nNắng sẽ về xua tan băng giá....\r\nVà em ngỡ như không rời xa...','vi','2025-12-07 00:40:22','2025-12-07 00:40:22'),(22,40,'Bae bae, em tự dưng muốn đi gym hằng ngày\r\nBae bae, em từ nay sẽ chăm skincare\r\nBae bae, em thề em sẽ chăm ăn healthy\r\nBae-bae-bae-bae-bae cuz\r\n\r\nMuốn nước da em da em da em mãi luôn trắng tươi hồng hào.\r\nMuốn có eo thon và gầy ôm trong vòng tay của anh.\r\nMuốn tấm thân em thân em thân em mãi luôn trẻ trung tràn trề\r\nBae-bae-bae cuz...\r\n\r\n[ĐK:]\r\nĐể anh vẫn luôn gọi em là em bé\r\nDẫu 40, 60, 80 anh vẫn luôn chung tình\r\nVẫn ủi an, chở che, cảm thông cho em đôi khi\r\nEm tự dưng lại nắng rồi em tự dưng lại mưa,\r\nHoặc đôi lần em ở giữa\r\n\r\nĐể anh vẫn luôn gọi em là em bé\r\nDẫu 40, 60, 80 em vẫn luôn như vậy\r\nVẫn thích anh, muốn anh, có anh ở đây bên em\r\nNhư là xương cần khớp, và như học sinh cần lớp\r\nLớp lớp lớp lớp\r\nLove you~\r\n\r\nBae bae bae bae bae bae babe x 4\r\n\r\n[RAP:]\r\nSo clean, so fresh...là những gì mà anh nghĩ về em\r\nNgày thường hay Tết....thiếu hơi 1 chút là không quen\r\nCứ mộc mạc đơn giản như mọi ngày, anh cũng đã tự say như điếu đổ\r\nNgười đã xinh lại còn đáng yêu như thế này, coi như từ nay là tim anh hết chỗ\r\n\r\nKhi em muốn thật hơn khi selfie, thì việc dễ nhất là ăn đồ healthy\r\nCòn nếu em tin là mình luôn hợp ý, vậy thì nghe anh thế này cho đỡ nghĩ\r\nEm ốm, anh ốm...em béo, anh béo theo\r\nEm sao, anh vậy, có thế nào thì anh vẫn lẽo đẽo...nên...\r\n\r\nĐừng quá lo lắng những thứ bề ngoài sẽ khiến tình cảm mình rẽ duyên\r\nChuyện nắng mưa trong em thất thường ra sao yên tâm ở đây có anh chia sẻ liền\r\nBất kể ngày hay đêm mặc định là anh cứ luôn nghiện em như kẻ điên\r\nCó tuột kí hay béo không phanh với anh vẫn không ai xinh bằng bé \"bi\"\r\n\r\nEm sợ mai này anh sẽ không còn thương em\r\nSẽ không còn ôm và hôn em mỗi ngày\r\nEm chỉ muốn rằng em mãi luôn là em bé\r\nVà anh sẽ luôn là của bé.\r\n\r\n[ĐK:]\r\nĐể anh vẫn luôn gọi em là em bé\r\nDẫu 40, 60, 80 anh vẫn luôn chung tình\r\nVẫn ủi an, chở che, cảm thông cho em đôi khi\r\nEm tự dưng lại nắng rồi em tự dưng lại mưa,\r\nHoặc đôi lần em ở giữa\r\n\r\nĐể anh vẫn luôn gọi em là em bé\r\nDẫu 40, 60, 80 em vẫn luôn như vậy\r\nVẫn thích anh, muốn anh, có anh ở đây bên em\r\nNhư là xương cần khớp, và như học sinh cần lớp\r\nLớp lớp lớp lớp\r\nLove you~','vi','2025-12-07 00:43:41','2025-12-07 00:43:41'),(23,41,'\"Cuộc đời này là màu hồng\" - mẹ nói lúc con ra đời\r\n\"Mỉm cười là điều tuyệt vời\" - mẹ nói lúc con lên 5\r\nDù răng con sún, chân không dài, vai chẳng thon\r\nMặt Trời còn dẹt một phần mà sao thế gian luôn cần?\r\n\"Hãy làm điều mình tự hào\" - mẹ nói lúc con lên 10\r\n\"Đừng làm điều mình ngần ngại\" - mẹ nói lúc con 12\r\nDù cho đôi lúc, con sai đường và quên lối đi\r\nTrưởng thành là điều tuyệt vời để từ sai ta học cho đúng.\r\nSau này năm con 22 sẽ thấy màu mắt của con thật xinh\r\nThấy giọng ca ngân nga trong vắt có khi lại khiến con rất đặc biệt\r\nVà hãy nhớ rằng trên đời này\r\nKhông ai phải giống ai\r\nNên là năm con 22\r\nHãy sống hồn nhiên giống như mưòi hai\r\nTình đầu là điều tuyệt vời mà con khắc ghi suốt đời.\r\nTừng chạm và từng dịu dàng làm tim của con rối bời\r\nĐừng quan tâm quá con sẽ cùng cậu ta đến đâu\r\nKỉ niệm là điều ở lại dù ai có không quay lại.\r\nSau này năm con 22 hãy vang lời ca của con muôn nơi\r\nMang tình yêu thương con đang giữ nhân ra tỏa khắp muôn phương chân trời.\r\nSẽ thật khó vì có đôi lần con sẽ cảm thấy chơi vơi\r\nNhưng chẳng sao khi con cho đi\r\nPhía sau đừng nghĩ sẽ nhận lại gì.\r\nHai mươi hai, hai mươi hai, hai mươi hai\r\nĐịa cầu là một hình tròn vậy nên thế gian xoay vòng\r\nĐiều mình nhận được là điều mình vô thức đã cho đi\r\nVậy nên sau nếu con có rời xa chốn đây\r\nĐừng sợ và đừng chần chờ vì đi cũng là để trở về.','vi','2025-12-07 00:45:14','2025-12-07 00:45:14'),(24,42,'Lời bài hát sẽ sớm được cập nhật...','vi','2025-12-07 00:46:22','2025-12-07 00:46:22'),(25,43,'Sao hôm nay, lại cứ ngẩn ngơ thế này\r\nSao mà bây giờ đây, vũ trụ em chỉ thấy anh thôi đấy\r\nBắt đền đi, trả lại tâm trí đâyy\r\nMeow meow meow meow, trả lại tâm trí tôi đây\r\n\r\nCứ như mèo con tắm nắng trong khu vườn nhà\r\nRất trong lành, có ong\r\nLòng em có anh\r\nMới chỉ được gặp anh mỗi lúc ban chiều là ưng\r\nQuá chừng lòng em cứ tứng tưng tưng\r\n\r\n(TONE UP)\r\n\r\nCứ như mèo con tắm nắng trong khu vườn nhà\r\nRất trong lành, có ong\r\nLòng em có anh\r\nMới chỉ được gặp anh mỗi lúc ban chiều là ưng\r\nQuá chừng lòng em cứ tứng tưng tưng\r\n\r\n(TONE UP)\r\n\r\nTone [***]\r\nsao hôm nay, lại cứ ngẩn ngơ thế này\r\nsao mà bây giờ đây, vũ trụ em chỉ thấy anh thôi đấy\r\nbắt đền đi, trả lại tâm trí đây\r\nmoew meow meow meow, trả lại tâm trí tôi đây\r\n\r\ncứ như mèo con tắm nắng trong khu vườn nhà\r\nrất trong lành, có ong lòng em có anh\r\nmới chỉ được gặp anh mỗi lúc ban chiều là ưng\r\nquá chừng lòng em cứ tứng tưng tưng','vi','2025-12-07 00:48:46','2025-12-07 00:48:46'),(26,44,'Bài hát : Santa Tell Me - Ariana Grande\r\n\r\nSanta tell me if you\'re really there\r\nDon\'t make me fall in love again\r\nIf he won\'t be here next year\r\nSanta tell me if he really cares\r\nCause I can give it all away if he won\'t be here next year\r\n\r\nFeeling Christmas all around\r\nAnd I\'m trying to play it cool\r\nBut it\'s hard to focus when I see him walking \'cross the room\r\nLet it snow, is blasting now\r\nBut I won\'t get it in the mood\r\nI\'m avoiding every mistletoe until I know it\'s true love\r\nThat he thinks of\r\nSo next Christmas I\'m not all alone boy\r\n\r\nSanta tell me if you\'re really there\r\nDon\'t make me fall in love again\r\nIf he won\'t be here next year\r\nSanta tell me if he really cares\r\nCause I can\'t give it all away if he won\'t be here next year\r\n\r\n\r\nI\'ve been down this road before\r\nFell in love on Christmas night\r\nBut I knew you say I woke up and you wasn\'t by my side\r\nNow I need someone to hold\r\nBe my fire in the cold\r\nBut it\'s hard to tell if this is just a fling or if it\'s true love\r\nThat he thinks of\r\nSo next Christmas I\'m not all alone boy\r\n\r\nSanta tell me if you\'re really there\r\nDon\'t make me fall in love again\r\nIf he won\'t be here next year\r\nSanta tell me if he really cares\r\nCause I can\'t give it all away if he won\'t be here next year\r\n\r\nOh I wanna have him beside me like ooh\r\nOn the 25th by the fireplace ooh\r\nBut I don\'t want no broken 